const { test } = require("@playwright/test");

test("beer pour scene runs", async ({ page }) => {
  const logs = [];
  page.on("console", msg => logs.push(`${msg.type()}: ${msg.text()}`));
  page.on("pageerror", err => logs.push(`pageerror: ${err.message}`));

  await page.setViewportSize({ width: 1280, height: 720 });
  await page.goto("http://127.0.0.1:8080/12.%20Particle%20Collisions/Main.html", { waitUntil: "load" });
  await page.mouse.move(900, 210);
  await page.mouse.down();
  await page.waitForTimeout(4200);
  await page.mouse.up();
  await page.waitForTimeout(1200);

  const stats = await page.evaluate(() => ({
    particles: playground.simulation.particles.length,
    foamParticles: playground.simulation.foamParticles.length,
    glassVolL: playground.simulation.glassVolL,
    bottleVolumeL: playground.simulation.bottleVolumeL,
    maxFoam: playground.simulation.particles.reduce((m, p) => Math.max(m, p.foam), 0),
    avgSurfaceFoam: (() => {
      let sum = 0;
      let count = 0;
      for(const p of playground.simulation.particles){
        if(p.surface > 0.2){
          sum += p.foam;
          count++;
        }
      }
      return count ? sum / count : 0;
    })()
  }));

  await page.screenshot({ path: "/tmp/beer-pour-check.png", fullPage: false });
  console.log(JSON.stringify({ logs, stats, screenshot: "/tmp/beer-pour-check.png" }, null, 2));
});

