    /* ---------- Glass ---------- */

    createGlass(){
        this.shapes = [];
        let g = this.glass;
        let wallColor = "rgba(150,170,150,0.0)";

        let topY = -g.height * 0.5;
        let bottomY = g.height * 0.5;
        let leftTop = new Vector2(-g.topWidth * 0.5, topY);
        let rightTop = new Vector2(g.topWidth * 0.5, topY);
        let leftBottom = new Vector2(-g.bottomWidth * 0.5, bottomY);
        let rightBottom = new Vector2(g.bottomWidth * 0.5, bottomY);

        this.leftGlassWall = this.createSegmentCollider(leftTop, leftBottom, g.wall, wallColor);
        this.rightGlassWall = this.createSegmentCollider(rightBottom, rightTop, g.wall, wallColor);
        this.glassBase = this.createSegmentCollider(leftBottom, rightBottom, g.wall * 1.4, wallColor);
        this.leftGlassWall.colliderRole = "wall";
        this.rightGlassWall.colliderRole = "wall";
        this.glassBase.colliderRole = "base";

        this.shapes.push(this.leftGlassWall);
        this.shapes.push(this.rightGlassWall);
        this.shapes.push(this.glassBase);
    }

    createSegmentCollider(localA, localB, thickness, color){
        let direction = Sub(localB, localA);
        direction.Normalize();
        let normal = direction.GetNormal();
        let half = thickness * 0.5;

        let vertices = [
            this.glassLocalToWorld(Add(localA, Scale(normal, -half))),
            this.glassLocalToWorld(Add(localB, Scale(normal, -half))),
            this.glassLocalToWorld(Add(localB, Scale(normal, half))),
            this.glassLocalToWorld(Add(localA, Scale(normal, half)))
        ];

        let polygon = new Polygon(vertices, color);
        let center = this.glassLocalToWorld(Scale(Add(localA, localB), 0.5));
        if(!polygon.isPointInside(center)){
            vertices.reverse();
            polygon = new Polygon(vertices, color);
        }

        return polygon;
    }

    glassLocalToWorld(local){
        let c = Math.cos(this.glass.angle);
        let s = Math.sin(this.glass.angle);
        return new Vector2(
            this.glass.center.x + local.x * c - local.y * s,
            this.glass.center.y + local.x * s + local.y * c
        );
    }

    worldToGlassLocal(world){
        let c = Math.cos(this.glass.angle);
        let s = Math.sin(this.glass.angle);
        let dx = world.x - this.glass.center.x;
        let dy = world.y - this.glass.center.y;
        return new Vector2(dx * c + dy * s, -dx * s + dy * c);
    }

    getGlassInteriorHalfWidth(localY){
        let g = this.glass;
        let y01 = Math.max(0, Math.min(1, (localY + g.height * 0.5) / g.height));
        let widthAtY = g.topWidth + (g.bottomWidth - g.topWidth) * y01;
        return Math.max(10, widthAtY * 0.5 - g.wall);
    }

    isInsideGlassInterior(pos){
        let local = this.worldToGlassLocal(pos);
        let g = this.glass;
        let halfWidth = this.getGlassInteriorHalfWidth(local.y);
        return local.x > -halfWidth &&
            local.x < halfWidth &&
            local.y > -g.height * 0.5 &&
            local.y < g.height * 0.5 - g.wall;
    }

    getGlassBeerVolumeL(){
        let count = 0;
        for(let i=0; i<this.particles.length; i++){
            if(this.isInsideGlassInterior(this.particles[i].position)){
                count++;
            }
        }
        return count * this.PARTICLE_LITERS;
    }

    getGlassFill01(){
        return Math.max(0, Math.min(1, this.getGlassBeerVolumeL() / this.GLASS_CAPACITY_L));
    }

    // Local Y of the beer surface inside the glass, derived from how full it is.
    getGlassSurfaceLocalY(){
        let fill = Math.max(0, Math.min(1.12, this.getGlassBeerVolumeL() / this.GLASS_CAPACITY_L));
        let bottom = this.glass.height * 0.5 - this.glass.wall;
        let usableHeight = this.glass.height * 0.82;
        return bottom - usableHeight * fill;
    }

