    /* ---------- Simulation step ---------- */

    // The hand holding the glass straightens it up as it fills, like a real pour.
    updateGlassTilt(dt){
        let t = this.smoothStep(Math.min(1, this.getGlassFill01() * 1.7));
        let target = this.glass.restAngle + (this.glass.uprightAngle - this.glass.restAngle) * t;
        let ease = 1 - Math.pow(0.2, dt);
        this.glass.angle += (target - this.glass.angle) * ease;
        this.createGlass();
    }

    update(dt){
        this.frame++;
        this.updateBottleFromPour();

        let maxSpawnFromBottle = Math.floor(this.bottleVolumeL / this.PARTICLE_LITERS);
        let spawned = this.emitter.spawn(dt, this.particles, this.MAX_PARTICLES, maxSpawnFromBottle);
        if(spawned > 0){
            this.bottleVolumeL = Math.max(0, this.bottleVolumeL - spawned * this.PARTICLE_LITERS);
        }

        this.neighbourSearch();
        this.buildNeighbors();
        this.glassVolL = this.getGlassBeerVolumeL();

        this.applyGravity(dt);
        this.applyBeerForces(dt);
        this.viscosity(dt);
        this.predictPositions(dt);

        for(let i=0; i<this.RELAX_ITERS; i++){
            this.doubleDensityRelaxation(dt);
        }

        this.handleOneWayCoupling(dt);
        this.worldBoundary();
        this.computeNextVelocity(dt);
        this.updateFoam(dt);
        this.diffuseFoam(dt);
        this.updateFoamParticles(dt);
        this.trimParticles();
    }

    neighbourSearch(){
        this.fluidHashGrid.clearGrid();
        this.fluidHashGrid.mapParticleToCell();
    }

    // Gather every particle's neighbours once into a flat list (CSR layout) so the
    // viscosity and density-relaxation passes don't re-scan the grid 3x per step.
    buildNeighbors(){
        let grid = this.fluidHashGrid;
        let cell = grid.cellSize;
        let map = grid.hashMap;
        let ps = this.particles;
        let n = ps.length;
        if(this.nbrStart.length < n + 1){
            this.nbrStart = new Int32Array(n + 1);
        }
        let idx = this.nbrIdx;
        idx.length = 0;
        for(let i=0; i<n; i++){
            this.nbrStart[i] = idx.length;
            let pos = ps[i].position;
            let gx = (pos.x / cell) | 0;
            let gy = (pos.y / cell) | 0;
            for(let dx=-1; dx<=1; dx++){
                for(let dy=-1; dy<=1; dy++){
                    let content = map.get(grid.cellIndexToHash(gx + dx, gy + dy));
                    if(content){
                        for(let m=0; m<content.length; m++){
                            let j = content[m];
                            if(j !== i){
                                idx.push(j);
                            }
                        }
                    }
                }
            }
        }
        this.nbrStart[n] = idx.length;
    }

    applyGravity(dt){
        for(let i=0; i< this.particles.length; i++){
            let p = this.particles[i];
            p.agitation = 0;   // re-measured each step in viscosity()
            p.cover = 0;       // how much beer sits on top of this particle
            p.impactFoam *= Math.pow(0.03, dt);
            p.wallSlide *= Math.pow(0.04, dt);
            p.velocity = Add(p.velocity, Scale(this.GRAVITY, dt));

            // Foam is lighter than beer: foamy particles float up and gather as a head.
            if(p.foam > 0.04 && this.isInsideGlassInterior(p.position)){
                p.velocity.y -= this.GRAVITY.y * this.FOAM_BUOYANCY * p.foam * dt;
            }
        }
    }

    applyBeerForces(dt){
        let glassVolume = this.glassVolL;
        let overflow = Math.max(0, (glassVolume - this.GLASS_CAPACITY_L) / this.GLASS_CAPACITY_L);
        let rimOut = new Vector2(-0.78, -0.18);
        rimOut.Normalize();
        let surfaceY = this.getGlassSurfaceLocalY();

        for(let i=0; i<this.particles.length; i++){
            let particle = this.particles[i];
            if(this.isInsideGlassInterior(particle.position)){
                let local = this.worldToGlassLocal(particle.position);
                let surfaceProximity = Math.max(0, 1 - Math.abs(local.y - surfaceY) / 42);
                let foamDrag = particle.foam * (0.12 + surfaceProximity * 0.25);
                particle.velocity.x *= Math.max(0.88, 1 - foamDrag * dt);
                particle.velocity.y *= Math.max(0.90, 1 - foamDrag * 0.7 * dt);
                particle.velocity = Scale(particle.velocity, 0.999);

                if(overflow > 0){
                    let surfaceBias = Math.max(0, 1 - (local.y + this.glass.height * 0.5) / (this.glass.height * 0.42));
                    particle.velocity = Add(particle.velocity, Scale(rimOut, overflow * surfaceBias * dt * 8));
                }
            }
        }
    }

    predictPositions(dt){
        for(let i=0; i< this.particles.length; i++){
            this.particles[i].prevPosition = this.particles[i].position.Cpy();
            let positionDelta = Scale(this.particles[i].velocity, dt * this.VELOCITY_DAMPING);
            this.particles[i].position = Add(this.particles[i].position, positionDelta);
        }
    }

    computeNextVelocity(dt){
        for(let i=0; i< this.particles.length; i++){
            let velocity = Scale(Sub(this.particles[i].position, this.particles[i].prevPosition), 1.0 / dt);
            this.particles[i].velocity = velocity;
        }
    }

    handleOneWayCoupling(dt){
        for(let i=0; i< this.particles.length; i++){
            let particle = this.particles[i];
            for(let j=0; j<this.shapes.length;j++){
                let dir = this.shapes[j].getDirectionOut(particle.position);
                if(dir != null){
                    let pen = dir.Length();
                    particle.position = Add(particle.position, dir);
                    if(pen > 0.0001){
                        // Slippery wall: cancel only the into-wall motion, keep the beer
                        // sliding down the glass instead of clinging to the edge.
                        let n = Scale(dir, 1 / pen);
                        let vn = particle.velocity.Dot(n);
                        let normalImpact = Math.max(0, -vn);
                        if(vn < 0){
                            particle.velocity = Sub(particle.velocity, Scale(n, vn));
                        }
                        let tangent = Sub(particle.velocity, Scale(n, particle.velocity.Dot(n)));
                        let tangentSpeed = tangent.Length();
                        let isWall = this.shapes[j].colliderRole === "wall";
                        let isBase = this.shapes[j].colliderRole === "base";

                        if(isWall){
                            particle.wallSlide = Math.max(particle.wallSlide, Math.min(1, tangentSpeed / 170));
                            particle.impactFoam += Math.max(0, normalImpact - 55) * 0.0018;
                            particle.velocity = Scale(particle.velocity, 0.985);
                        }else if(isBase){
                            particle.impactFoam += Math.max(0, normalImpact - 30) * 0.0045;
                            particle.velocity.x *= 0.96;
                            particle.velocity.y *= 0.88;
                        }else{
                            particle.velocity = Scale(particle.velocity, 0.99);
                        }
                        particle.prevPosition = Sub(particle.position, Scale(particle.velocity, dt));
                    }
                }
            }
        }
    }

    doubleDensityRelaxation(dt){
        let ps = this.particles;
        let nbr = this.nbrIdx;
        let start = this.nbrStart;
        let R = this.INTERACTION_RADIUS;
        let R2 = R * R;
        let invR = 1 / R;
        let dt2 = dt * dt;
        let K = this.K;
        let KNEAR = this.K_NEAR;
        let REST = this.REST_DENSITY;

        for(let i=0; i<ps.length; i++){
            let pa = ps[i];
            let pax = pa.position.x;
            let pay = pa.position.y;
            let s = start[i];
            let e = start[i+1];

            let density = 0;
            let densityNear = 0;
            for(let k=s; k<e; k++){
                let pb = ps[nbr[k]];
                let rx = pb.position.x - pax;
                let ry = pb.position.y - pay;
                let d2 = rx*rx + ry*ry;
                if(d2 < R2){
                    let omq = 1 - Math.sqrt(d2) * invR;
                    density += omq*omq;
                    densityNear += omq*omq*omq;
                }
            }

            let pressure = K * (density - REST);
            let pressureNear = KNEAR * densityNear;
            let dax = 0;
            let day = 0;

            for(let k=s; k<e; k++){
                let pb = ps[nbr[k]];
                let rx = pb.position.x - pax;
                let ry = pb.position.y - pay;
                let d2 = rx*rx + ry*ry;
                if(d2 >= R2){
                    continue;
                }
                let dist = Math.sqrt(d2);
                if(dist < 0.0001){
                    rx = Math.random() - 0.5;
                    ry = Math.random() - 0.5;
                    dist = Math.sqrt(rx*rx + ry*ry);
                }
                let omq = 1 - dist * invR;
                let disp = dt2 * (pressure * omq + pressureNear * omq * omq);
                let f = 0.5 * disp / dist;
                let dx = rx * f;
                let dy = ry * f;
                pb.position.x += dx;
                pb.position.y += dy;
                dax -= dx;
                day -= dy;
            }

            pa.position.x += dax;
            pa.position.y += day;
        }
    }

    viscosity(dt){
        let ps = this.particles;
        let nbr = this.nbrIdx;
        let start = this.nbrStart;
        let R = this.INTERACTION_RADIUS;
        let R2 = R * R;
        let invR = 1 / R;
        let SIG = this.SIGMA;
        let BET = this.BETA;

        for(let i=0; i<ps.length; i++){
            let pa = ps[i];
            let pax = pa.position.x;
            let pay = pa.position.y;
            let vax = pa.velocity.x;   // snapshot of A's velocity for this particle's pass
            let vay = pa.velocity.y;
            let s = start[i];
            let e = start[i+1];

            for(let k=s; k<e; k++){
                let pb = ps[nbr[k]];
                let rx = pb.position.x - pax;
                let ry = pb.position.y - pay;
                let d2 = rx*rx + ry*ry;
                if(d2 >= R2 || d2 < 1e-8){
                    continue;
                }
                let dist = Math.sqrt(d2);
                let nx = rx / dist;
                let ny = ry / dist;
                let u = (vax - pb.velocity.x) * nx + (vay - pb.velocity.y) * ny;
                let omq = 1 - dist * invR;

                // Relative motion = local turbulence -> nucleates foam at the splash.
                let stir = omq * Math.abs(u);
                pa.agitation += stir;
                pb.agitation += stir;
                // How buried each particle is (neighbours above it): ry<0 means B above A.
                if(ry < 0){ pa.cover += omq; }
                else{ pb.cover += omq; }

                if(u > 0){
                    let ITerm = dt * omq * (SIG * u + BET * u * u) * 0.5;
                    let ix = nx * ITerm;
                    let iy = ny * ITerm;
                    pa.velocity.x -= ix;
                    pa.velocity.y -= iy;
                    pb.velocity.x += ix;
                    pb.velocity.y += iy;
                }
            }
        }
    }

    worldBoundary(){
        let tableY = this.glass.center.y + this.glass.height * 0.5 + 2;
        for(let i=0; i< this.particles.length; i++){
            let p = this.particles[i];
            let pos = p.position;

            if(pos.x < 0){
                pos.x = 0;
                p.prevPosition.x = 0;
            }
            if(pos.y < 0){
                pos.y = 0;
                p.prevPosition.y = 0;
            }
            if(pos.x > canvas.width){
                pos.x = canvas.width-1;
                p.prevPosition.x = canvas.width-1;
            }
            // Spilled beer pools on the table the glass stands on, not the screen edge.
            if(pos.y > tableY && !this.isInsideGlassInterior(pos)){
                pos.y = tableY;
                p.prevPosition.y = tableY;
            }
            if(pos.y > canvas.height){
                pos.y = canvas.height-1;
                p.prevPosition.y = canvas.height-1;
            }
        }
    }

    trimParticles(){
        // Drop particles that have spilled off the table so they don't pile up forever.
        for(let i=this.particles.length - 1; i>=0; i--){
            let p = this.particles[i];
            if(p.position.y > canvas.height - 4 && !this.isInsideGlassInterior(p.position)){
                p.deadTimer = (p.deadTimer || 0) + 1;
                if(p.deadTimer > 90){
                    this.particles.splice(i, 1);
                }
            }
        }
        if(this.particles.length > this.MAX_PARTICLES){
            this.particles.splice(0, this.particles.length - this.MAX_PARTICLES);
        }
    }

    /* ---------- Foam ---------- */

    updateFoam(dt){
        for(let i=0; i<this.particles.length; i++){
            let p = this.particles[i];
            p.age += dt;
            p.turbulence *= 0.95;
            let inGlass = this.isInsideGlassInterior(p.position);
            let coverSurface = Math.max(0, Math.min(1, 1 - p.cover / this.SURFACE_COVER));
            let headSurface = 0;
            let belowHead = 0;
            if(inGlass){
                let local = this.worldToGlassLocal(p.position);
                let surfaceY = this.getGlassSurfaceLocalY();
                belowHead = Math.max(0, local.y - surfaceY);
                headSurface = Math.max(0, Math.min(1, 1 - belowHead / 78));
            }
            p.surface = inGlass ? headSurface : coverSurface;

            // Turbulence above a quiescent threshold whips dissolved CO2 into foam.
            // Beer sliding gently down the wall stays below it -> almost no foam.
            // The stream plunging into the pool blows past it -> a thick head.
            let stir = p.agitation - this.FOAM_THRESHOLD;
            let wallPourSuppression = 1 - p.wallSlide * 0.68;
            let surfaceBoost = 0.30 + p.surface * 1.15;
            let impact = Math.min(1, p.impactFoam);
            if((stir > 0 || impact > 0.02) && inGlass){
                // Turbulence whips up foam. A hard plunge churns a lot; beer sliding
                // gently down the wall barely crosses the threshold.
                let generated = Math.max(0, stir) * this.FOAM_GEN * surfaceBoost * wallPourSuppression;
                generated += impact * 2.4 * surfaceBoost;
                p.foam = Math.min(1, p.foam + generated * dt);
                let burstChance = (Math.max(0, stir - 820) * 0.00002 + impact * 0.035) * wallPourSuppression;
                if(this.foamParticles.length < this.MAX_FOAM_PARTICLES && Math.random() < burstChance){
                    this.createFoamBurst(p.position, 0.35 + Math.min(1.25, Math.max(0, stir) * 0.001 + impact * 0.75));
                }
            }

            // Foam under a head of beer collapses fast (pressure); foam at the free
            // surface lasts. Buoyancy lifts foam up, so a head gathers on top and the
            // body below clears - the head thickness self-limits as lower bubbles burst.
            let decayRate = this.FOAM_DECAY * (1 + p.cover * p.cover * 0.95);
            if(!inGlass){
                decayRate += 0.09;   // spilled beer loses its foam (reads as amber, not white)
            }
            if(p.surface < 0.25){
                decayRate += 0.035;  // bubbles trapped under beer collapse into liquid quickly
            }
            if(belowHead > 95){
                decayRate += 0.06;
            }
            p.foam -= p.foam * decayRate * dt;
        }
    }

    diffuseFoam(dt){
        let ps = this.particles;
        let nbr = this.nbrIdx;
        let start = this.nbrStart;
        let R = this.INTERACTION_RADIUS;
        let R2 = R * R;
        let invR = 1 / R;
        let rate = 0.18 * dt;

        for(let i=0; i<ps.length; i++){
            let pa = ps[i];
            if(pa.foam <= 0.02 && pa.surface <= 0.08){
                continue;
            }

            let s = start[i];
            let e = start[i + 1];
            for(let k=s; k<e; k++){
                let j = nbr[k];
                if(j < i){
                    continue;
                }

                let pb = ps[j];
                let rx = pb.position.x - pa.position.x;
                let ry = pb.position.y - pa.position.y;
                let d2 = rx * rx + ry * ry;
                if(d2 >= R2){
                    continue;
                }

                let surface = Math.max(pa.surface, pb.surface);
                if(surface <= 0.06){
                    continue;
                }

                let omq = 1 - Math.sqrt(d2) * invR;
                let transfer = (pa.foam - pb.foam) * rate * omq * (0.35 + surface * 0.9);
                pa.foam = Math.max(0, Math.min(1, pa.foam - transfer));
                pb.foam = Math.max(0, Math.min(1, pb.foam + transfer));
            }
        }
    }

    createFoamBurst(position, intensity){
        let amount = Math.max(1, Math.floor(1 + intensity * 2.5));
        for(let i=0; i<amount && this.foamParticles.length < this.MAX_FOAM_PARTICLES; i++){
            let angle = Math.random() * Math.PI * 2;
            let radius = Math.random() * 8 * intensity;
            let pos = Add(position, new Vector2(Math.cos(angle) * radius, Math.sin(angle) * radius));
            let vel = new Vector2(
                (Math.random() - 0.5) * (9 + intensity * 7),
                -6 - Math.random() * (8 + intensity * 8)
            );
