    drawFoam(targetCtx){
        targetCtx.fillStyle = "white";
        targetCtx.globalAlpha = 1;

        // The head IS the foamy beer particles, which buoyancy has floated to the top.
        // No scripted band - wherever foam physically is, that is where it draws.
        let r = window.FOAM_RADIUS;
        for(let i=0; i<this.particles.length; i++){
            let p = this.particles[i];
            if(p.foam <= this.FOAM_RENDER_MIN){
                continue;
            }
            let f = Math.min(1, (p.foam - this.FOAM_RENDER_MIN) / (1 - this.FOAM_RENDER_MIN));
            let surface = Math.max(0, Math.min(1, p.surface || 0));
            if(surface <= 0.06){
                continue;
            }
            targetCtx.globalAlpha = Math.max(0.18, Math.min(1, f * (0.35 + surface * 0.8)));
            targetCtx.beginPath();
            targetCtx.arc(p.position.x, p.position.y, r * (0.45 + f * 0.45 + surface * 0.25), 0, Math.PI * 2);
            targetCtx.fill();
        }
        targetCtx.globalAlpha = 1;

        // Airborne splash flecks.
        for(let i=0; i<this.foamParticles.length; i++){
            let foam = this.foamParticles[i];
            let alpha = Math.max(0, Math.min(1, foam.life / foam.maxLife));
            let rr = foam.radius * (0.7 + (1 - alpha) * 0.3);
            targetCtx.beginPath();
            targetCtx.arc(foam.position.x, foam.position.y, rr, 0, Math.PI * 2);
            targetCtx.fill();
        }
    }

    drawBeerDetails(targetCtx){
        targetCtx.save();

        // Rising bubbles and bright specular flecks inside the settled beer.
        for(let i=0; i<this.particles.length; i += 6){
            let p = this.particles[i];
            if(!this.isInsideGlassInterior(p.position)){
                continue;
            }
            if(i % 12 === 0){
                let bob = Math.sin(this.frame * 0.05 + i) * 2;
                let bubbleR = 1.1 + ((i * 17) % 5) * 0.4;
                targetCtx.globalAlpha = 0.5;
                targetCtx.beginPath();
                targetCtx.arc(p.position.x + bob, p.position.y - 3, bubbleR, 0, Math.PI * 2);
                targetCtx.strokeStyle = "rgba(255,247,205,0.8)";
                targetCtx.lineWidth = 1;
                targetCtx.stroke();
            }
        }

        targetCtx.restore();
        targetCtx.globalAlpha = 1;
    }

    drawFoamDetails(targetCtx){
