    playground.angle = playground.MIN_ANGLE;
    playground.pouring = true;
    playground.simulation.setBottleAngle(playground.MIN_ANGLE);
  });
  const samples = [];
  for (let i = 0; i < 6; i++) {
    await page.waitForTimeout(1000);
